'use strict';
let animationReview=null;
document.body.insertAdjacentHTML('beforeend','<dialog id="animationReview"><h2 id="animationReviewTitle">Review animation</h2><canvas id="animationReviewCanvas" width="640" height="360"></canvas><input id="animationReviewTime" type="range" min="0" step="0.02"><p id="animationReviewStatus" role="status"></p><button id="applyAnimationReview">Apply</button><button id="cancelAnimationReview">Cancel</button></dialog><input id="replaceCharacterArtFile" type="file" accept="image/png,image/jpeg,image/webp" hidden>');
function reviewActorChange(o,next,title){if(o.locked)throw Error('Unlock this character first.');stop();const s=current(),candidate=structuredClone(project);candidate.scenes[sceneIndex].objects[s.objects.indexOf(o)]=next;if(!valid(candidate))throw Error('This edit would leave invalid animation.');animationReview={id:o.id,scene:s.id,next,signature:JSON.stringify(project)};$('animationReviewTitle').textContent=title;$('animationReviewTime').max=s.duration;$('animationReviewTime').value=Math.min(time,s.duration);$('animationReviewStatus').textContent='Preview the result at different times. Apply keeps the existing animation; Undo restores the previous version.';$('animationReview').showModal();paintAnimationReview()}
function paintAnimationReview(){if(!animationReview)return;const s=project.scenes.find(s=>s.id===animationReview.scene),copy={...s,objects:s.objects.map(o=>o.id===animationReview.id?animationReview.next:o)};const previous=project;try{project={...project,scenes:project.scenes.map(scene=>scene.id===copy.id?copy:scene)};renderSceneFrame($('animationReviewCanvas').getContext('2d'),copy,+$('animationReviewTime').value)}finally{project=previous}}
$('animationReviewTime').oninput=paintAnimationReview;$('cancelAnimationReview').onclick=()=>$('animationReview').close();$('applyAnimationReview').onclick=()=>{if(!animationReview||JSON.stringify(project)!==animationReview.signature)return $('animationReviewStatus').textContent='The project changed. Prepare the preview again.';const s=project.scenes.find(s=>s.id===animationReview.scene),i=s.objects.findIndex(o=>o.id===animationReview.id);s.objects[i]=animationReview.next;save();render();$('animationReview').close()};
function detectFootSlides(o,start=clipStart(o),end=clipEnd(o)){const frames=[];for(let t=start;t<=end+.001;t+=1/15){const v=stateAt(o,t);frames.push({t,v,left:footForPose(o,'left',v,t).point,right:footForPose(o,'right',v,t).point})}const findings=[];for(const side of ['left','right']){const floor=Math.max(...frames.map(f=>f[side].y));let run=[];const flush=()=>{if(run.length>=4){const first=run[0],last=run.at(-1),drift=Math.hypot(last[side].x-first[side].x,last[side].y-first[side].y);if(drift>3)findings.push({side,start:first.t,end:last.t,drift})}run=[]};for(const frame of frames){if(frame[side].y>=floor-3)run.push(frame);else flush()}flush()}return findings}
function reviewFootCorrection(o,finding){const next=buildMotionCleanup(o,{start:finding.start,end:finding.end,plant:finding.side,smoothing:0});reviewActorChange(o,next,'Correct '+finding.side+' foot contact')}
async function replaceCharacterArtwork(o,file){if(o.type!=='puppet'||o.locked)throw Error('Choose an unlocked picture character.');if(file.size>16e6)throw Error('Choose artwork smaller than 16 MB.');const src=await dataURL(file),image=await imageReady(src),art=characterAtView(o),atlas=document.createElement('canvas');atlas.width=art.imageWidth;atlas.height=art.imageHeight;const g=atlas.getContext('2d'),scale=Math.min(atlas.width/image.naturalWidth,atlas.height/image.naturalHeight);g.drawImage(image,(atlas.width-image.naturalWidth*scale)/2,(atlas.height-image.naturalHeight*scale)/2,image.naturalWidth*scale,image.naturalHeight*scale);const next=structuredClone(o),replacement=rigArtwork(art);replacement.imageSrc=replacement.originalImageSrc=atlas.toDataURL('image/png');for(const part of replacement.parts){const c=document.createElement('canvas');c.width=Math.ceil(part.width);c.height=Math.ceil(part.height);const context=c.getContext('2d');context.drawImage(atlas,part.x,part.y,part.width,part.height,0,0,c.width,c.height);context.globalCompositeOperation='destination-in';context.drawImage(await imageReady(part.src),0,0,c.width,c.height);part.src=part.originalSrc=c.toDataURL('image/png');await imageReady(part.src)}if(o.characterViews)attachCharacterView(next,characterViewAt(o),replacement);else Object.assign(next,replacement,{name:o.name});reviewActorChange(o,next,'Replace artwork · check joint alignment');$('animationReviewStatus').textContent='The new picture is fitted to the existing cut-outs. Check alignment and every joint. Different poses or silhouettes may need new cut-outs.'}
$('replaceCharacterArtFile').onchange=e=>{const f=e.target.files[0],o=object();e.target.value='';if(f&&o)replaceCharacterArtwork(o,f).catch(e=>toast(e.message))};
function suggestSpeechGestures(o){if(o.locked)throw Error('Unlock the character first.');const s=current(),offset=storySceneOffset(s),ids=new Set(storyLines(s).filter(l=>l.speakerId===o.id).map(l=>l.audioId));if(o.speechTrackId)ids.add(o.speechTrackId);const proposals=[];for(const c of tracks().filter(c=>ids.has(c.id))){const buffer=audioBuffers.get(c.id);if(!buffer)continue;const samples=buffer.getChannelData(0),energies=[];for(let t=c.start;t<audioEnd(c);t+=.2){let sum=0,n=0;const from=Math.floor((c.offset+(t-c.start)*(c.rate||1))*buffer.sampleRate);for(let i=from;i<Math.min(samples.length,from+buffer.sampleRate*.15);i+=8){sum+=samples[i]**2;n++}energies.push({at:t-offset,rms:Math.sqrt(sum/Math.max(1,n))})}const mean=energies.reduce((n,x)=>n+x.rms,0)/Math.max(1,energies.length);for(let i=1;i<energies.length-1;i++){const e=energies[i];if(e.at<0||e.at+.7>s.duration||e.rms<Math.max(.015,mean*1.1)||e.rms<energies[i-1].rms||e.rms<energies[i+1].rms||proposals.some(p=>Math.abs(p.at-e.at)<1))continue;if((s.storyCues||[]).some(p=>p.actorId===o.id&&p.at<e.at+.7&&p.at+p.duration>e.at))continue;proposals.push({id:uid(),actorId:o.id,at:e.at,duration:.7,emotion:'neutral',action:heldProps(s,o.id,e.at).length?'nod':proposals.length%2?'nod':'talk',targetId:null,intensity:.45,speechSuggested:true})}}return proposals.slice(0,40)}
function showSpeechSuggestions(o){const cues=suggestSpeechGestures(o),next=structuredClone(o);if(!cues.length)return toast('No distinct speech accents found. Try a longer linked voice, or add gestures in Script.');const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Suggested speech gestures</h2><p>Suggestions follow audio accents. Choose what fits the performance.</p>';const list=document.createElement('div');for(const cue of cues){const row=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=true;check.onchange=()=>cue.skip=!check.checked;const length=storyNumber(cue.duration,.2,Math.min(2,current().duration-cue.at),v=>cue.duration=v,'Gesture length'),strength=storyNumber(cue.intensity,.1,1,v=>cue.intensity=v,'Gesture strength'),action=storySelect([['nod','Head nod'],['talk','Hand gesture']],cue.action,v=>cue.action=v,'Suggested action');row.append(check,document.createTextNode(cue.at.toFixed(1)+'s '),action,length,strength);list.append(row)}dialog.append(list,storyButton('Apply selected',()=>{if(o.locked||!current().objects.includes(o))return toast('The character changed.');const selected=cues.filter(c=>!c.skip);if((current().storyCues||[]).length+selected.length>200)return toast('Too many reaction cues in this scene.');(current().storyCues??=[]).push(...selected.map(c=>{delete c.skip;return c}));save();render();dialog.close()}),storyButton('Close',()=>dialog.close()));dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}
const paintBeforeSmoothTurns=paintPuppet;paintPuppet=function(c,o,v,t=time){const key=(o.viewKeys||[]).filter(k=>k.t<=t).at(-1),duration=o.viewBlend||0;if(!duration||!key||t>=key.t+duration)return paintBeforeSmoothTurns(c,o,v,t);const previous=characterAtView(o,Math.max(0,key.t-.001)),next=characterAtView(o,t),f=clamp((t-key.t)/duration,0,1),smooth=f*f*(3-2*f);paintBeforeSmoothTurns(c,{...previous,characterViews:undefined,viewKeys:undefined},{...v,opacity:v.opacity*(1-smooth)},t);paintBeforeSmoothTurns(c,{...next,characterViews:undefined,viewKeys:undefined},{...v,opacity:v.opacity*smooth},t)};
const stateBeforeTurnAnticipation=stateAt;stateAt=function(o,t){const v=stateBeforeTurnAnticipation(o,t),duration=o.viewBlend||0,key=(o.viewKeys||[]).find(k=>t>=k.t-duration/2&&t<=k.t+duration/2);if(key&&duration)v.headTilt+=Math.sin((t-key.t+duration/2)/duration*Math.PI)*3;return v};
const controlsBeforeRefinements=renderControls;renderControls=function(){controlsBeforeRefinements();const o=object();if(!isAnimatedCharacter(o))return;const panel=document.createElement('details');panel.innerHTML='<summary>Refine this performance</summary>';const walk=document.createElement('input');walk.type='checkbox';walk.checked=!!o.naturalWalk;walk.onchange=()=>{o.naturalWalk=walk.checked;save();draw()};panel.append(storyLabel('Natural walk starts and stops',walk),storyButton('Check foot sliding',()=>{try{const found=detectFootSlides(o);const list=panel.querySelector('.foot-findings');list.replaceChildren();if(!found.length)list.textContent='No sustained near-ground foot sliding detected.';for(const f of found)list.append(storyButton(f.side+' foot · '+f.start.toFixed(1)+'–'+f.end.toFixed(1)+'s · preview correction',()=>{try{reviewFootCorrection(o,f)}catch(e){toast(e.message)}}))}catch(e){toast(e.message)}}),Object.assign(document.createElement('div'),{className:'foot-findings'}),storyButton('Suggest gestures from voice',()=>{try{showSpeechSuggestions(o)}catch(e){toast(e.message)}}));if(o.type==='puppet'){panel.append(storyLabel('View turn blend (seconds)',storyNumber(o.viewBlend||0,0,.8,value=>{o.viewBlend=value;save();draw()},'View turn blend')),storyButton('Replace artwork, keep animation',()=>$('replaceCharacterArtFile').click()))}panel.querySelectorAll('button,input').forEach(e=>e.disabled=!!o.locked);($('controls').querySelector('[data-character-panel="animate"]')||$('controls')).append(panel)};
